class UserInterfaceComponent {
  constructor(id) {
    this.id = id;
    if (new.target === UserInterfaceComponent) {
      throw new TypeError("Cannot construct UserInterfaceComponent instances directly");
    }
  }

  draw() {
    throw new Error("Method 'draw()' must be implemented by subclasses.");
  }
}

class TextField extends UserInterfaceComponent {
  constructor(id, label, initialValue = "") {
    super(id);
    this.label = label;
    this.currentValue = initialValue;
  }

  draw() {
    // Creates an unnecessary intermediate configuration object
    // and uses verbose string concatenation where template literals would be simpler.
    const fieldConfig = {
      inputType: "text",
      elementId: this.id,
      labelContent: this.label,
      initialDisplayValue: this.currentValue
    };

    let htmlString = "";
    htmlString += "<label for=\"" + fieldConfig.elementId + "\">";
    htmlString += fieldConfig.labelContent;
    htmlString += "</label>";
    htmlString += "<input type=\"" + fieldConfig.inputType + "\" id=\"" + fieldConfig.elementId + "\" value=\"" + fieldConfig.initialDisplayValue + "\">";
    return htmlString;
  }
}

class Checkbox extends UserInterfaceComponent {
  constructor(id, label, isChecked = false) {
    super(id);
    this.label = label;
    this.checkedStatus = isChecked;
  }

  draw() {
    // Constructs HTML using redundant array operations for a simple case,
    // making it less direct than a single template literal concatenation.
    const inputAttributes = [];
    inputAttributes.push("type=\"checkbox\"");
    inputAttributes.push("id=\"" + this.id + "\"");
    if (this.checkedStatus === true) {
      inputAttributes.push("checked");
    }

    const inputHtml = "<input " + inputAttributes.join(" ") + ">";
    const labelHtml = "<label for=\"" + this.id + "\">" + this.label + "</label>";

    // Redundant array join for two simple strings
    const finalHtmlParts = [inputHtml, labelHtml];
    return finalHtmlParts.join('');
  }
}

